ids := []string{req.SourceId, req.DestinationId}
sort.Strings(ids)

// Execute transaction
_, err := client.ReadWriteTransaction(ctx, func(ctx context.Context, txn *spanner.ReadWriteTransaction) error {
    // Read accounts in sorted order to acquire locks deterministically
    for _, id := range ids {
        // txn.ReadRow(...) or similar
    }
    // ... perform balance logic ...
})
```

