#### Step 1: Account Service Implementation (Go Example)
*Assuming a Go-based gRPC implementation. Adjustments can be made for Java/Node.js if specified.*

```go
package service

import (
	"context"
	"errors"
	"log"

	pb "github.com/your-repo/generated/account"
	"github.com/your-repo/repository"
)

type AccountServiceServer struct {
	pb.UnimplementedAccountServiceServer
	Repo repository.AccountRepository
}

func (s *AccountServiceServer) UpdateAccount(ctx context.Context, req *pb.UpdateAccountRequest) (*pb.AccountResponse, error) {
	// 1. Fetch existing account
	account, err := s.Repo.FindByID(req.AccountId)
	if err != nil {
		return nil, errors.New("account not found")
	}

	// 2. Handle Partial Patch for Status
	// If req.Status is nil, it was omitted in the gRPC call (equivalent to legacy null)
	if req.Status != nil {
		newStatus := req.Status.Value
		if isValidStatus(newStatus) {
			account.Status = newStatus
		} else {
			return nil, errors.New("invalid status value")
		}
	}

	// 3. Persist changes
	updatedAccount, err := s.Repo.Save(account)
	if err != nil {
		return nil, err
	}

	return &pb.AccountResponse{
		AccountId: updatedAccount.ID,
		Status:    updatedAccount.Status,
	}, nil
}

func isValidStatus(status string) bool {
	return status == "ACTIVE" || status == "INACTIVE"
}
```

