### 1. Implementation: Middleware Logic

#### `internal/middleware/cors.go`
This implementation uses a strict whitelist and anchored regex to prevent subdomain takeover.

```go
package middleware

import (
	"net/http"
	"regexp"
	"strings"

	"github.com/gin-gonic/gin"
)

var (
	// Strict anchored regex for dynamic subdomains
	dynamicOriginRegex = regexp.MustCompile(`^https://[a-zA-Z0-9-]+\.example\.com$`)
	staticWhitelist    = map[string]bool{
		"https://dashboard.example.com": true,
		"https://admin.example.com":     true,
	}
)

func StrictCORSMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		origin := c.GetHeader("Origin")
		if origin == "" {
			c.Next()
			return
		}

		// Validate Origin
		allowed := false
		if staticWhitelist[origin] || dynamicOriginRegex.MatchString(origin) {
			allowed = true
		}

		if allowed {
			c.Header("Access-Control-Allow-Origin", origin)
			c.Header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
			c.Header("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With")
			c.Header("Access-Control-Allow-Credentials", "true")
		}

		// Handle Preflight
		if c.Request.Method == http.MethodOptions {
			c.AbortWithStatus(http.StatusNoContent)
			return
		}

		c.Next()
	}
}
```

#### `internal/middleware/rate_limit.go`
This implementation provides the required `X-RateLimit` headers.

```go
package middleware

import (
	"net/http"
	"strconv"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

type visitor struct {
	lastSeen time.Time
	count    int
}

var (
	visitors = make(map[string]*visitor)
	mu       sync.Mutex
	limit    = 100
	window   = 60 * time.Second
)

func RateLimitMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		ip := c.ClientIP()
		mu.Lock()
		v, exists := visitors[ip]
		if !exists || time.Since(v.lastSeen) > window {
			visitors[ip] = &visitor{lastSeen: time.Now(), count: 1}
			v = visitors[ip]
		} else {
			v.count++
		}
		mu.Unlock()

		resetTime := v.lastSeen.Add(window).Unix()
		remaining := limit - v.count

		c.Header("X-RateLimit-Limit", strconv.Itoa(limit))
		c.Header("X-RateLimit-Remaining", strconv.Itoa(max(0, remaining)))
		c.Header("X-RateLimit-Reset", strconv.FormatInt(resetTime, 10))

		if v.count > limit {
			c.AbortWithStatusJSON(http.StatusTooManyRequests, gin.H{"error": "Rate limit exceeded"})
			return
		}

		c.Next()
	}
}

func max(a, b int) int {
	if a > b { return a }
	return b
}
```

