package service

import (
	"context"
	"encoding/json"
	"fmt"
	"log"

	"github.com/segmentio/kafka-go"
	"payment-service/internal/repository"
	paymentv1 "payment-service/gen/proto/payment/v1"
)

type PaymentConsumer struct {
	reader *kafka.Reader
	repo   *repository.PaymentRepository
}

func NewPaymentConsumer(brokers []string, topic string, groupID string, repo *repository.PaymentRepository) *PaymentConsumer {
	return &PaymentConsumer{
		reader: kafka.NewReader(kafka.ReaderConfig{
			Brokers:  brokers,
			Topic:    topic,
			GroupID:  groupID,
			MinBytes: 10e3, // 10KB
			MaxBytes: 10e6, // 10MB
		}),
		repo: repo,
	}
}

func (c *PaymentConsumer) Run(ctx context.Context) error {
	log.Printf("Starting PaymentReceivedEvent consumer...")
	defer c.reader.Close()

	for {
		msg, err := c.reader.FetchMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				return nil
			}
			log.Printf("Error fetching message: %v", err)
			continue
		}

		var event paymentv1.PaymentReceivedEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			log.Printf("Error unmarshaling event: %v", err)
			// In production, move to Dead Letter Queue (DLQ)
			c.reader.CommitMessages(ctx, msg)
			continue
		}

		// Process event with idempotency logic
		err = c.repo.ProcessPaymentEvent(ctx, &event)
		if err != nil {
			log.Printf("Failed to process payment %s: %v", event.PaymentId, err)
			// Depending on error type, decide whether to retry or commit (skip)
			continue
		}

		if err := c.reader.CommitMessages(ctx, msg); err != nil {
			log.Printf("Failed to commit message: %v", err)
		}
	}
}
