```go
package repository

import (
	"context"
	"database/sql"
	"errors"
	"fmt"

	paymentv1 "payment-service/gen/proto/payment/v1"
)

type PaymentRepository struct {
	db *sql.DB
}

func (r *PaymentRepository) ProcessPaymentEvent(ctx context.Context, event *paymentv1.PaymentReceivedEvent) error {
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// 1. Check for existing record to handle duplicates/out-of-order
	var status string
	err = tx.QueryRowContext(ctx, 
		"SELECT status FROM payments WHERE payment_id = $1 FOR UPDATE", 
		event.PaymentId).Scan(&status)

	if err == nil {
		// Record exists. If it's already processed, skip.
		if status == "COMPLETED" {
			return nil // Already processed, idempotent success
		}
		// If it's a retry of a failed state, we might update it here.
	} else if !errors.Is(err, sql.ErrNoRows) {
		return fmt.Errorf("failed to query payment: %w", err)
	}

	// 2. Insert or Update the payment record
	_, err = tx.ExecContext(ctx, `
		INSERT INTO payments (payment_id, amount, currency, status, created_at)
		VALUES ($1, $2, $3, 'COMPLETED', NOW())
		ON CONFLICT (payment_id) DO UPDATE 
		SET status = 'COMPLETED' 
		WHERE payments.status != 'COMPLETED'`,
		event.PaymentId, event.AmountCents, event.Currency)

	if err != nil {
		return fmt.Errorf("failed to upsert payment: %w", err)
	}

	// 3. Log the event in an audit/idempotency table
	_, err = tx.ExecContext(ctx, `
		INSERT INTO processed_events (event_id, payment_id, processed_at)
		VALUES ($1, $2, NOW())
		ON CONFLICT DO NOTHING`,
		fmt.Sprintf("pay_%s_%d", event.PaymentId, event.Timestamp), event.PaymentId)

	if err != nil {
		return fmt.Errorf("failed to log processed event: %w", err)
	}

	return tx.Commit()
}
